contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // We accept an amount to forward to c.go; this function is payable so caller can supply funds to this test
    function run(uint amount) public payable {
        require(address(this).balance >= amount, "insufficient balance to forward");
        // Observe owner before the call
        address ownerBefore = c.owner();
        // record balances before
        uint balCBefore = address(c).balance;
        uint balThisBefore = address(this).balance;

        bool reverted;
        // call c.go forwarding `amount` Wei
        try c.go{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe after-values
        address ownerAfter = c.owner();
        uint balCAfter = address(c).balance;
        uint balThisAfter = address(this).balance;

        // If the call succeeded (did not revert) then owner must remain non-zero and unchanged,
        // contract balance must be zero (funds forwarded out), and this contract's balance must have
        // increased by exactly the amount that was previously held by c plus any forwarded amount that ended up returned here.
        // We express a general invariant: if success then owner unchanged and c.balance == 0 and this balance >= balThisBefore - amount (cannot underflow),
        // and the increase in this contract's balance is at most balCBefore + amount.
        // To keep it provable and general we assert exact: success => ownerAfter == ownerBefore && ownerAfter != address(0) && balCAfter == 0
        // and balThisAfter >= balThisBefore - amount && balThisAfter <= balThisBefore + balCBefore + amount;
        assert(reverted || (ownerAfter == ownerBefore && ownerAfter != address(0) && balCAfter == 0 && balThisAfter >= balThisBefore - amount && balThisAfter <= balThisBefore + balCBefore + amount));
    }
    // allow receiving ether from c or calls
    receive() external payable {}
}

